with filtered as (select *, concat(carrier, ' ', status) as carrier_status from shipments where shipped_date > date '2023-03-31' and delivered_date <= '2024-08-23'), enriched as (select *, sum(cost) over (partition by status, carrier order by shipped_date, id rows between 3 preceding and current row) as last4_sum_cost, max(cost) over (partition by status, carrier order by shipped_date, id rows between 3 preceding and current row) as last4_max_cost, count(cost) over (partition by status, carrier order by shipped_date, id rows between 3 preceding and current row) as last4_count_cost, round(cost / sum(cost) over (partition by status), 4) as cost_share from filtered), metrics as (select *, lag(cost_share) over w_hist as prev_cost_share, lead(cost_share) over w_hist as next_cost_share, lead(cost) over w_hist as next_cost, row_number() over w_hist as row_seq from enriched window w_hist as (partition by order_id, carrier order by last4_max_cost, id)), with_dims as (select e.*, b.status as order_status, b.channel, b.discount from metrics e left join orders b on e.order_id = b.id), filtered_shipments as (select id, carrier, shipped_date, cost, status, carrier_status, last4_sum_cost, last4_max_cost, last4_count_cost, cost_share, prev_cost_share, next_cost, channel, discount, round(discount, 2) as discount_rounded, coalesce(carrier, 'UNKNOWN') as carrier_clean from with_dims where shipped_date > date '2023-07-27' and carrier is distinct from 'DHL') select id, carrier, kpi, metric_value from (select id, carrier, cost, next_cost, last4_max_cost, discount_rounded from filtered_shipments) src unpivot (metric_value for kpi in (cost as COST_VAL, next_cost as NEXT_COST, last4_max_cost as LAST4_MAX_COST_VAL, discount_rounded as DISCOUNT_ROUNDED))
